WITH flattened_attrs AS (SELECT id, plan, tier_limits, tier_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT CASE WHEN entry_price >= 29 THEN 'LARGE' ELSE 'SMALL' END AS entry_price_tier, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, PERCENTILE_APPROX(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, ROUND(AVG(entry_price), 2) AS avg_entry_price FROM flattened_attrs GROUP BY CASE WHEN entry_price >= 29 THEN 'LARGE' ELSE 'SMALL' END;
